                                r = 2 * H - 2 - r
                        for kc in range(K):
                            q = ocol * S + kc * D - P
                            if padding_mode == "zeros":
                                if not 0 <= q < W:
                                    continue
                            else:
                                if q < 0:
                                    q = -q
                                if q >= W:
                                    q = 2 * W - 2 - q
                            xi = (c * H + r) * W + q
                            wi = ((o * CPG + cl) * K + kr) * K + kc
                            product = snapshot_x[xi] * snapshot_w[wi]
                            if not math.isfinite(product):
